<script lang="ts">
  import {page} from '$app/state'; import {replaceState} from '$app/navigation'; import MapViewport from '$lib/components/map/MapViewport.svelte'; import AppIcon from '$lib/components/ui/AppIcon.svelte'; import PageHeader from '$lib/components/shell/PageHeader.svelte'; import graphData from '$lib/data/math-building/graph.json'; import {findRoute} from '$lib/domain/navigation/a-star'; import {splitRouteByFloor} from '$lib/domain/navigation/route-builder'; import {spaces,floorDisplayName} from '$lib/domain/navigation/spaces'; import {getLocationAnchorByNode} from '$lib/domain/navigation/anchors'; import type {FloorId,GraphData} from '$lib/domain/navigation/types'; import type {SheetSnapPoint} from '$lib/ui/design-system';
  const graph=graphData as GraphData; const floorLabels:Record<FloorId,string>={ground:'Ground',second:'2nd',third:'3rd'}; const floorIds:FloorId[]=['ground','second','third']; const initialId=page.url.searchParams.get('room'); const initialSpace=spaces.find(s=>s.id===initialId)??null; const requestedStartNodeId=page.url.searchParams.get('from'); const startNode=graph.nodes.find(n=>n.id===requestedStartNodeId)??graph.nodes.find(n=>n.id==='gf-main-entrance')!; const startAnchor=getLocationAnchorByNode(startNode.id);
  let floor=$state<FloorId>(initialSpace?.floor??'ground'); let selectedSpaceId=$state<string|null>(initialSpace?.id??null); let query=$state(''); let activeRoute=$state<ReturnType<typeof findRoute>>(page.url.searchParams.get('route')==='1'&&initialSpace?.doorNode?findRoute(graph,startNode.id,initialSpace.doorNode):null); let sheetSnap=$state<SheetSnapPoint>('peek'); const selected=$derived(spaces.find(s=>s.id===selectedSpaceId)??null); const normalized=$derived(query.trim().toLowerCase().replaceAll(' ','')); const results=$derived(normalized.length<1?[]:spaces.filter(s=>[s.name,s.subtitle,...(s.aliases??[])].filter(Boolean).join(' ').toLowerCase().replaceAll(' ','').includes(normalized)).slice(0,7)); const segments=$derived(activeRoute?splitRouteByFloor(graph,activeRoute):[]); const routeNodeIdsForFloor=$derived(segments.find(s=>s.floor===floor)?.points.map(n=>n.id)??[]); const floorSpaces=$derived(spaces.filter(s=>s.floor===floor));
  function selectSpace(id:string){selectedSpaceId=id;const space=spaces.find(i=>i.id===id);if(space)floor=space.floor;query='';activeRoute=null;sheetSnap='peek';const url=new URL(page.url);url.searchParams.set('room',id);replaceState(url,page.state);} function startRoute(){if(!selected?.doorNode)return;activeRoute=findRoute(graph,startNode.id,selected.doorNode);if(activeRoute)floor=startNode.floor;} function clearSelection(){selectedSpaceId=null;activeRoute=null;const url=new URL(page.url);url.searchParams.delete('room');url.searchParams.delete('route');replaceState(url,page.state);}
  const sheetHeight=$derived(sheetSnap==='expanded'?'max-h-[calc(100svh-12rem-env(safe-area-inset-bottom))]':sheetSnap==='half'?'max-h-[48svh]':'max-h-56');
</script>
<svelte:head><title>Building Map · IMS Academic Hub</title><meta name="description" content="Interactive schematic floor explorer for the UPLB IMS Math Building."/></svelte:head>
<div class="mx-auto grid w-full max-w-[1180px] gap-4 px-4 py-6 sm:px-6 sm:py-8"><PageHeader eyebrow="Indoor explorer" title="Math Building" description={`Search a room or facility and inspect the structured floor map. Prototype routes start at ${startAnchor?.shortLabel??startNode.label}.`} /><div class="flex flex-wrap items-center gap-2"><span class="border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-ims-blue-ink">Start · {startAnchor?.shortLabel??startNode.label}</span>{#if startAnchor}<a class="min-h-11 py-3 text-sm font-bold text-ims-blue-ink" href={`/loc/${startAnchor.slug}`}>Anchor Details</a>{/if}</div>
<section class="relative z-10 border border-line-strong bg-white p-2"><label class="grid gap-1 text-sm font-bold" for="room-search"><span>Search the building</span><input class="min-h-12 border border-line-strong px-3 text-base outline-none focus:border-ims-blue-deep focus-visible:ring-3 focus-visible:ring-ims-blue/20" id="room-search" bind:value={query} placeholder="Try “MB 304,” “Math Clinic,” or “CR”…" autocomplete="off"/></label>{#if results.length}<div class="absolute left-2 right-2 top-[calc(100%-2px)] divide-y divide-line border border-line-strong bg-white shadow-xl" role="listbox" aria-label="Room search results">{#each results as result}<button class="flex min-h-14 w-full items-center justify-between gap-3 px-3 py-2 text-left hover:bg-sky-50" type="button" role="option" aria-selected={result.id===selectedSpaceId} onclick={()=>selectSpace(result.id)}><span class="grid"><strong>{result.name}</strong>{#if result.subtitle}<small class="text-muted">{result.subtitle}</small>{/if}</span><span class="text-xs font-bold text-muted">{floorLabels[result.floor]}</span></button>{/each}</div>{/if}</section>
<div class="grid grid-cols-3 gap-1 bg-slate-200 p-1" role="group" aria-label="Choose floor">{#each floorIds as floorId}<button class={`min-h-11 font-bold ${floor===floorId?'bg-white text-ims-blue-ink shadow-sm':'text-muted hover:bg-white/60'}`} type="button" aria-pressed={floor===floorId} onclick={()=>floor=floorId}>{floorLabels[floorId]}</button>{/each}</div>
<section class="overflow-hidden border border-line-strong bg-white p-3" aria-labelledby="map-floor-title"><header class="mb-3 flex items-end justify-between gap-3"><div><p class="font-mono text-xs uppercase tracking-[.12em] text-ims-blue-ink">Schematic floorplan</p><h2 class="text-xl font-semibold" id="map-floor-title">{floorDisplayName(floor)}</h2></div><span class="border border-yellow-300 bg-yellow-50 px-2 py-1 text-xs font-bold text-amber-900">Needs site verification</span></header><MapViewport {floor} {selectedSpaceId} routeNodeIds={routeNodeIdsForFloor} onSelect={selectSpace}/></section>
{#if activeRoute&&segments.length>1}<section class="grid gap-3 border-l-4 border-ims-yellow bg-white p-4 sm:grid-cols-[1fr_auto] sm:items-center" aria-label="Route floor segments"><div><p class="font-mono text-xs uppercase tracking-[.12em] text-ims-blue-ink">Route</p><strong>Follow the highlighted floor segments</strong></div><div class="flex flex-wrap gap-2">{#each segments as segment,index}<button class={`min-h-11 border px-3 font-bold ${floor===segment.floor?'border-amber-400 bg-yellow-50 text-amber-900':'border-line bg-white'}`} type="button" onclick={()=>floor=segment.floor}>{floorLabels[segment.floor]}{index<segments.length-1?' →':''}</button>{/each}</div></section>{/if}
<div class="grid gap-4 lg:grid-cols-[.9fr_1.1fr]">
<section class={`grid content-start gap-3 border border-line-strong bg-white p-4 ${selected?`fixed bottom-[calc(6rem+env(safe-area-inset-bottom))] left-2 right-2 z-40 overflow-auto overscroll-contain shadow-2xl lg:static lg:max-h-none lg:shadow-none ${sheetHeight}`:''}`} aria-live="polite" aria-label={selected?'Selected room details':'Room details'} data-snap={sheetSnap}>{#if selected}<div class="flex justify-center gap-1 lg:hidden" role="group" aria-label="Room details height">{#each [['peek','Peek','Show compact room details'],['half','Half','Show half-height room details'],['expanded','Full','Expand room details']] as option}<button class={`min-h-9 rounded-full border px-2 text-xs font-bold ${sheetSnap===option[0]?'border-ims-blue-deep bg-sky-50 text-ims-blue-ink':'border-line'}`} type="button" aria-label={option[2]} aria-pressed={sheetSnap===option[0]} onclick={()=>sheetSnap=option[0] as SheetSnapPoint}>{option[1]}</button>{/each}</div><header class="grid grid-cols-[1fr_auto] gap-3"><div><p class="font-mono text-xs uppercase tracking-[.12em] text-ims-blue-ink">{floorDisplayName(selected.floor)}</p><h2 class="font-mono text-3xl font-semibold">{selected.name}</h2><p class="capitalize text-muted">{selected.subtitle??selected.kind.replaceAll('-',' ')}</p></div><button class="grid size-11 place-items-center border border-line" type="button" onclick={clearSelection} aria-label="Close room details"><AppIcon name="close" size={18}/></button></header><div class="flex flex-wrap gap-2"><a class="inline-flex min-h-11 items-center border border-line-strong px-3 font-bold no-underline" href={`/room/${selected.id}`}>Room Details</a>{#if selected.doorNode}<button class="min-h-11 bg-ims-blue-deep px-3 font-bold text-white" type="button" onclick={startRoute}>Route from {startAnchor?.shortLabel??startNode.label}</button>{/if}</div><p class="text-xs text-muted">Geometry status: {selected.verificationStatus.replaceAll('-',' ')}.</p>{:else}<div><p class="font-mono text-xs uppercase tracking-[.12em] text-ims-blue-ink">Select a destination</p><h2 class="text-2xl font-semibold">Tap a room on the map.</h2><p class="text-muted">Or use the search field above.</p></div>{/if}</section>
<details class="border border-line-strong bg-white p-4" open><summary class="cursor-pointer list-none border-b border-line pb-3"><p class="font-mono text-xs uppercase tracking-[.12em] text-ims-blue-ink">Text alternative</p><h2 class="text-2xl font-semibold">Places on this floor</h2></summary><div class="mt-3 divide-y divide-line border-y border-line">{#each floorSpaces as space}<button class={`flex min-h-14 w-full items-center justify-between gap-3 border-l-4 px-3 py-2 text-left ${space.id===selectedSpaceId?'border-ims-blue-deep bg-sky-50':'border-transparent bg-white hover:bg-slate-50'}`} type="button" onclick={()=>selectSpace(space.id)}><span class="grid"><strong>{space.name}</strong><small class="capitalize text-muted">{space.subtitle??space.kind.replaceAll('-',' ')}</small></span><span aria-hidden="true">→</span></button>{/each}</div></details></div></div>
